 async function action(body,message){setBusy(true);setFormError('');try{const r=await fetch('/api/platform',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Error(d.error);setNotice(typeof message==='function'?message(d):message);setModal(null);await load();return d}catch(e){setFormError(e.message);setNotice('');throw e}finally{setBusy(false)}}
 const run=(body,message)=>action(body,message).catch(()=>{});
 function changeTab(t){setFilterAgency('');setTab(t);setQuery('');setFilterCountry('Sve države');setLegal('Svi statusi');setPrice('');setSourceKind('Sve prilike');setMatchStatus('Svi rezultati');setPage(1);setMenu(false);setFormError('')}
 // changeTab clears the other tab filters; the tested target state is then applied explicitly.
